import React, { Component } from 'react'
import Container from 'react-bootstrap/Container'
import CommentersTable from './CommentersTable';
import SearchForm from './SearchForm';

class App extends Component {

  state = {
    commenters: [
      ],
    showCommentersTable: false,

    showSearchSubmitButton: true,
    showSearchSubmitLoadingButton: false,

    showCommentersSubmitButton: false,
    showCommentersSubmitLoadingButton: false
  }

  /*removeCharacter = index => {
      const { commenters } = this.state

      this.setState({
        formData: commenters.filter((commenters, i) => {
          return i !== index
        }),
      })
  } */

  render() {

    const { commenters } = this.state
    const { showCommentersTable } = this.state

    const { showSearchSubmitButton } = this.state
    const { showSearchSubmitLoadingButton } = this.state

    const { showCommentersSubmitButton } = this.state
    const { showCommentersSubmitLoadingButton } = this.state

      return (
        <Container>
            <h3>Search</h3>
            <SearchForm handleSearchSubmit={this.handleSearchSubmit} showSearchSubmitButton={showSearchSubmitButton} showSearchSubmitLoadingButton={showSearchSubmitLoadingButton} />
            <CommentersTable
                commenters={commenters}
                showCommentersTable={showCommentersTable}
                handleCommentersSubmit={this.handleCommentersSubmit}
                showCommentersSubmitButton={showCommentersSubmitButton}
                showCommentersSubmitLoadingButton={showCommentersSubmitLoadingButton}
                />
        </Container>
      )
  }

  handleSearchSubmit = formData => {

    this.setState({ showSearchSubmitButton: false })
    this.setState({ showSearchSubmitLoadingButton: true })

    const requestOptions = {
        method: 'GET'//,
        //headers: { 'Content-Type': 'application/json' },
        //body: JSON.stringify(formData)
    };
    fetch('https://google.com', requestOptions)
        .then(async response => {
            //const data = await response.json();
            const data = [{profileUrl: "https://soundcloud.com/patrickxtaylor", messagedBefore: "Yes"},
            {profileUrl: "https://soundcloud.com/alvonmars", messagedBefore: "No"},
            {profileUrl: "https://soundcloud.com/upukrecords", messagedBefore: "No"},
            {profileUrl: "https://soundcloud.com/user-355158966-477119345", messagedBefore: "No"},
            {profileUrl: "https://soundcloud.com/deftsoulmusique1995", messagedBefore: "No"},
            {profileUrl: "https://soundcloud.com/ocmoon", messagedBefore: "Yes"}
            ];

            console.log(data);
            // check for error response
            if (!response.ok) {
                // get error message from body or default to response status
                const error = (data && data.message) || response.status;
                return Promise.reject(error);
            }

            this.setState({ commenters: data })
            this.setState({ showCommentersTable: true })

            this.setState({ showSearchSubmitButton: true })
            this.setState({ showSearchSubmitLoadingButton: false })
        })
        .catch(error => {
            //this.setState({ errorMessage: error.toString() });
            console.error('There was an error!', error);
            this.setState({ showSearchSubmitButton: true })
            this.setState({ showSearchSubmitLoadingButton: false })
        });


      //this.setState({ commenters: [...this.state.commenters] })
  }



  handleCommentersSubmit = formData => {

    console.log(formData);

  }

}

export default App
